func (sh *strictHandler) LookupTenants(w http.ResponseWriter, r *http.Request, params LookupTenantsParams) {
	var request LookupTenantsRequestObject

	request.Params = params

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.LookupTenants(ctx, request.(LookupTenantsRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "LookupTenants")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(LookupTenantsResponseObject); ok {
		if err := validResponse.VisitLookupTenantsResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

